source(file.path(dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value=TRUE)[1]), mustWork=FALSE)), "backend_common.R"))
opts<-parse_cli_args();require_args(opts,c("outdir"));set.seed(as.integer(opts$seed%||%1));n<-as.integer(opts$n%||%12); scenarios<-c("aligned_movement","heterogeneous_movement","no_movement","return_oriented","zero_vectors");out<-bind_rows(lapply(scenarios,function(s){M<-switch(s,aligned_movement=matrix(rnorm(n*2,1,.1),n),heterogeneous_movement=matrix(rnorm(n*2),n),no_movement=matrix(0,n,2),return_oriented=matrix(c(rnorm(n,1,.1),rnorm(n,-1,.1)),n),zero_vectors=matrix(c(rep(0,n),rnorm(n)),n));tibble(scenario=s,mean_magnitude=mean(sqrt(rowSums(M^2))),mean_loo_reference_cosine=mean(compute_loo_cosines(M),na.rm=TRUE))}));write_tsv_safe(out,file.path(ensure_outdir(opts$outdir),"response_geometry_simulator.tsv"))
